insert into public.followup_resources(domain,kind,category,name,definition,objective,protocol,source_note) values
('mentale','habilete','Habiletés fondamentales','Confiance en soi','Perception de sa capacité à mobiliser ses ressources et à réussir une tâche dans un contexte donné. Elle se construit et varie selon les situations.','Identifier les expériences de maîtrise, les ressources et les repères personnels qui soutiennent la confiance.','Explorer une situation précise, ce qui a été réussi et les actions mobilisées ; formuler un repère concret à réutiliser.','Cours utilisateur « Motivation et Confiance », partie confiance en soi et auto-efficacité.'),
('mentale','habilete','Autorégulation','Stress','Réponse d’une personne lorsqu’elle évalue qu’une situation comporte des exigences ou un enjeu. Son intensité et ses effets dépendent de la situation et des ressources perçues.','Repérer les exigences, les signes corporels et mentaux, et les ressources disponibles.','Décrire une situation, les signes physiques et mentaux, leur moment d’apparition et leur effet sur l’action.','Cours utilisateur « Le Stress / L’anxiété / Les émotions », M1 EOPS 2025-2026.'),
('mentale','habilete','Autorégulation','Anxiété','Réponse d’inquiétude et d’appréhension liée à une situation anticipée ; elle peut comporter des pensées préoccupantes et des sensations corporelles.','Distinguer les préoccupations, les sensations et les besoins de préparation propres à la situation.','Explorer les déclencheurs, les pensées anticipatoires, les sensations et les stratégies déjà utilisées ; suivre leur évolution dans le temps.','Cours utilisateur « Le Stress / L’anxiété / Les émotions », M1 EOPS 2025-2026 ; CSAI-2 du classeur.'),
('mentale','habilete','Autorégulation','Régulation des émotions','Capacité à reconnaître et comprendre ses émotions et à choisir une réponse adaptée au contexte, sans supposer qu’une émotion doive disparaître.','Développer la conscience des signaux émotionnels et choisir une action compatible avec la tâche.','Nommer l’émotion, repérer son intensité et son effet, puis tester une stratégie d’action ou de recentrage adaptée.','Cours utilisateur « Le Stress / L’anxiété / Les émotions », M1 EOPS 2025-2026.'),
('mentale','habilete','Habiletés fondamentales','Motivation','Ensemble de processus qui déclenchent, orientent, intensifient et maintiennent un comportement dans le temps.','Comprendre ce qui donne du sens à la pratique et soutient l’engagement.','Explorer plaisir, valeurs, sentiment de compétence, autonomie, appartenance et raisons de poursuivre ; définir un pas d’action choisi.','Cours utilisateur « Motivation et Confiance », Vallerand et Thill ; autodétermination.'),
('mentale','habilete','Habiletés cognitives','Attention et concentration','Capacité à orienter et maintenir l’attention sur les informations utiles, et à la réorienter lorsqu’elle est captée par une distraction.','Repérer les indices pertinents et entraîner le retour à la tâche.','Choisir un ou deux indices adaptés à l’action, repérer les distracteurs et convenir d’un signal bref de retour.','Cours utilisateur « Attention Concentration » et « YD.Switch.2025.2026 ».'),
('mentale','habilete','Habiletés psycho-somatiques','Activation','Niveau d’énergie et d’éveil ressenti par le sportif, à ajuster aux exigences de la tâche et à ses préférences.','Identifier le niveau d’activation que le sportif juge utile dans une situation précise.','Décrire sensations et niveau d’énergie avant/après une stratégie ; tester une option choisie sans imposer un niveau universel.','Cours utilisateur « Motivation et Confiance » et OMSAT du classeur vierge.'),
('mentale','habilete','Habiletés cognitives','Imagerie mentale','Répétition mentale d’une action ou d’une situation, avec des images et sensations évoquées par la personne.','Préparer une action, une routine ou une réponse à une difficulté dans un scénario réaliste.','Choisir un scénario et une perspective ; préciser les sensations utiles, le rythme et la réponse à mobiliser ; vérifier la vivacité et le confort.','Cours utilisateur sur l’imagerie mentale (SIQ, MIQ, KVIQ et cours étudiants 2025-2026).'),
('mentale','habilete','Habiletés cognitives','Discours interne','Paroles ou pensées adressées à soi-même, spontanées ou intentionnelles, qui peuvent informer, motiver ou participer à la régulation.','Repérer les consignes qui accompagnent l’action et tester une formulation personnelle utile.','Partir d’une situation vécue et noter pensées, émotions et effets sur la pratique ; essayer une consigne courte, crédible et orientée vers l’action.','Cours utilisateur « Discours interne.pdf ».'),
('mentale','habilete','Habiletés de base','Fixation d’objectifs','Définition de repères qui orientent l’action et permettent d’observer la progression, en distinguant processus, performance et résultat.','Transformer une intention en étapes observables et réévaluables.','Formuler un objectif choisi, spécifique et daté ; identifier une action sous le contrôle du sportif et un indicateur de suivi.','Cours utilisateur « Fixations dobjectifs.pdf » et « Motivation et Confiance ».'),
('mentale','habilete','Autorégulation','Résilience','Processus d’adaptation et de reprise après une difficulté, en tenant compte des ressources et du contexte de la personne.','Identifier les ressources déjà mobilisées et les prochaines options accessibles.','Revenir sur une difficulté, distinguer ce qui dépend ou non du sportif et choisir une action progressive de reprise.','Cours utilisateur « Motivation et Confiance », compétences fondamentales GMP-SP présentées dans le cours stress/émotions.'),
('mentale','habilete','Autorégulation','Relaxation','Ensemble de pratiques visant notamment une baisse du tonus musculaire et une adaptation respiratoire, selon le cours de relaxation.','Explorer une stratégie de relâchement qui reste confortable et adaptée à la personne.','Choisir une pratique brève, vérifier le confort avant et après, et interrompre ou adapter en cas d’inconfort.','Cours utilisateur « YD. Techniques de Relaxation.2025.2026.pdf ».'),
('mentale','methode','Objectifs','Objectifs de processus et de performance','Distinguer ce que la personne veut obtenir, les repères de performance et les actions qu’elle peut réaliser.','Donner un cap et des actions concrètes sous le contrôle du sportif.','Clarifier l’intention ; traduire en objectif de performance et en deux repères de processus ; choisir date et point de révision.','Cours utilisateur « Fixations dobjectifs.pdf » et « Motivation et Confiance », développement de la motivation.'),
('mentale','methode','Confiance','Carnet de preuves de maîtrise','Revenir sur des expériences où le sportif a mobilisé des ressources et progressé.','Rendre visibles les actions et apprentissages qui soutiennent le sentiment de compétence.','Après entraînement ou match, noter une action réussie, le comportement qui l’a rendue possible et un repère à réutiliser.','Cours utilisateur « Motivation et Confiance », sentiment de compétence et auto-efficacité.'),
('mentale','methode','Discours interne','Tableau de dialogue interne','Outil de réflexion reliant une situation, les pensées et émotions, leurs conséquences et une reformulation testable.','Comprendre ce qui se passe dans une situation sportive précise et construire une consigne crédible.','Compléter : situation ; pensées ; émotions / ressentis ; conséquence sur la pratique ; pensée reformulée ; mots-clés à tester.','Onglet « Kendra outils » du classeur « Modele_vierge_preparation_mentale.xlsx » et « Discours interne.pdf ».'),
('mentale','methode','Switch mental','Scan · Stop · focalisation','Séquence de repérage d’une alerte, déclenchement d’un signal choisi et retour de l’attention vers un repère utile.','Préparer une réponse courte aux pensées ou perceptions qui éloignent l’attention de la tâche.','1. Repérer ses alertes. 2. Choisir un déclencheur de switch. 3. Recentrer l’attention sur une consigne, image ou sensation utile. Répéter avec une situation concrète.','Cours utilisateur « YD.Switch.2025.2026.pdf », étapes Scan, déclenchement, focalisation.'),
('mentale','methode','Respiration et relaxation','Respiration confortable avec expiration prolongée','Pratique d’observation et d’ajustement léger de la respiration, sans forcer ni imposer d’apnée.','Tester une respiration que la personne juge confortable pour faciliter le retour au calme.','Observer la respiration naturelle ; si c’est confortable, laisser l’expiration durer légèrement plus longtemps ; arrêter ou revenir au naturel en cas d’inconfort.','Cours utilisateur « YD. Techniques de Relaxation.2025.2026.pdf », respirations relaxantes et respiration ventrale.'),
('mentale','methode','Respiration et relaxation','Balayage corporel','Déplacement progressif de l’attention à travers des zones du corps et leurs sensations.','Développer le repérage des sensations et du relâchement corporel.','Guider l’attention sur les zones en contact avec le sol puis les autres parties du corps ; proposer plusieurs respirations confortables et vérifier les ressentis.','Cours utilisateur « YD. Techniques de Relaxation.2025.2026.pdf », balayage corporel.'),
('mentale','methode','Respiration et relaxation','Relâchement progressif inspiré de Jacobson','Pratique qui alterne prise de conscience et relâchement des tensions musculaires.','Aider la personne à repérer ses tensions et à différencier tension et relâchement.','Présenter la consigne, choisir quelques groupes musculaires et une intensité faible ; relâcher puis observer les sensations. Adapter et interrompre si douleur ou gêne.','Cours utilisateur « YD. Techniques de Relaxation.2025.2026.pdf », méthode Jacobson.'),
('mentale','methode','Imagerie','Imagerie de réussite réaliste','Répétition mentale d’une action maîtrisable, avec des repères sensoriels et attentionnels choisis.','Préparer une action ou routine précise et renforcer la familiarité avec ses repères.','Définir une scène courte, une perspective, le rythme et les sensations pertinentes ; imaginer l’action et recueillir le ressenti ensuite.','Cours utilisateur sur l’imagerie mentale ; OMSAT et supports SIQ/MIQ/KVIQ.'),
('mentale','methode','Imagerie','Imagerie d’adaptation','Répétition mentale d’une situation avec une difficulté réaliste et la réponse souhaitée.','Préparer un plan d’action et un retour à la tâche après un imprévu.','Choisir une difficulté précise, identifier les indices d’alerte, imaginer une réponse réaliste puis la reprise de l’action. Vérifier que le scénario reste tolérable.','Cours utilisateur sur l’imagerie mentale et gestion du stress ; méthode à adapter individuellement.'),
('mentale','methode','Attention','Repères attentionnels et retour à la tâche','Identification d’indices pertinents et d’une action de recentrage courte.','Réduire le temps passé sur la distraction et réorienter l’attention vers la prochaine action.','Pour une situation donnée, choisir un indice externe ou interne ; après distraction/erreur, utiliser un signal convenu puis reprendre l’indice choisi.','Cours utilisateur « Attention Concentration » et « YD.Switch.2025.2026.pdf ».'),
('mentale','methode','Motivation','Explorer les raisons de pratiquer','Repérage des motifs de pratique, du plaisir, des valeurs et des besoins psychologiques de compétence, autonomie et appartenance.','Comprendre les appuis et les freins de l’engagement selon le point de vue du sportif.','Questions ouvertes sur ce qui plaît, ce qui compte, ce qui donne le sentiment de progresser et les choix que la personne souhaite faire ; convenir d’une action.','Cours utilisateur « Motivation et Confiance », autodétermination de Deci et Ryan.'),
('mentale','methode','Préparation compétition','Routine précompétitive souple','Organisation de repères avant l’épreuve, avec une consigne et une option d’adaptation.','Réduire l’incertitude et soutenir l’attention sans rendre la routine rigide.','Choisir des étapes utiles avant l’épreuve, une consigne d’action, un repère de respiration ou d’activation si souhaité, puis une option si le plan change.','Classeur « Modele_vierge_preparation_mentale.xlsx », OMSAT — préparation à la compétition ; adaptation au sportif.')
