-- Bibliothèque de méthodes et d’habiletés pour la rédaction des séances
-- À exécuter après 20261112_followup_admin.sql dans Supabase > SQL Editor.
create table if not exists public.followup_resources (
 id uuid primary key default gen_random_uuid(),
 domain text not null default 'mentale' check (domain in ('mentale','physique','clubs_entreprises','basket_individuel')),
 kind text not null check (kind in ('methode','habilete')),
 category text not null default '',
 name text not null,
 definition text not null default '',
 objective text not null default '',
 protocol text not null default '',
 source_note text not null default '',
 active boolean not null default true,
 created_at timestamptz not null default now(),
 unique(domain,kind,name)
);
create index if not exists followup_resources_active_idx on public.followup_resources(domain,kind,category,active);
alter table public.followup_resources enable row level security;
drop policy if exists "followup admin resources" on public.followup_resources;
create policy "followup admin resources" on public.followup_resources for all to authenticated using (public.is_admin()) with check (public.is_admin());

on conflict(domain,kind,name) do update set
 category=excluded.category,definition=excluded.definition,objective=excluded.objective,
 protocol=excluded.protocol,source_note=excluded.source_note,active=true;
